from typing import *
from collections import *

class Solution:
    def totalNumbers(self, digits: List[int]) -> int:
        # Count occurrences of each digit
        count = Counter(digits)

        # Initialize the count of valid numbers
        count_valid_numbers = 0

        # Iterate over all possible combinations of three digits
        for i in range(1, 4):
            for j in range(i+1, 5):
                for k in range(j+1, 6):
                    # Check if all digits in the combination are even
                    if all(digit % 2 == 0 for digit in [digits[i-1], digits[j-1], digits[k-1]]):
                        # Calculate the number of ways to arrange the digits in the combination
                        count_valid_numbers += count[digits[i-1]] * count[digits[j-1]] * count[digits[k-1]]

        return count_valid_numbers

from typing import *
from collections import *

class Solution:
    def totalNumbers(self, digits: List[int]) -> int:
        # Check if any digit is even
        has_even = False
        for digit in digits:
            if digit % 2 == 0:
                has_even = True
                break

        # If no even digit is present, return 0
        if not has_even:
            return 0

        # Sort the digits to ensure we always pick the smallest possible even digit first
        digits.sort()

        # Initialize count of valid three-digit even numbers
        count = 0

        # Iterate through each possible choice for the hundreds place
        for i in range(len(digits)):
            # Ensure the hundreds digit is even
            if digits[i] % 2 == 0:
                # Iterate through each possible choice for the tens place
                for j in range(i + 1, len(digits)):
                    # Ensure the tens digit is even and different from the hundreds digit
                    if digits[j] % 2 == 0 and digits[j] != digits[i]:
                        # Iterate through each possible choice for the units place
                        for k in range(j + 1, len(digits)):
                            # Ensure the units digit is even and different from both the hundreds and tens digits
                            if digits[k] % 2 == 0 and digits[k] != digits[i] and digits[k] != digits[j]:
                                # Increment the count of valid three-digit even numbers
                                count += 1

        return count
